// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.WechatApp.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(wechatapp.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *WechatAppUpsertBulk) UpdateNewValues() *WechatAppUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(wechatapp.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(wechatapp.FieldCreatedAt)
			}
			if _, exists := b.mutation.WxAppID(); exists {
				s.SetIgnore(wechatapp.FieldWxAppID)
			}
			if _, exists := b.mutation.AppType(); exists {
				s.SetIgnore(wechatapp.FieldAppType)
			}
			if _, exists := b.mutation.Connection(); exists {
				s.SetIgnore(wechatapp.FieldConnection)
			}
			if _, exists := b.mutation.PlatformID(); exists {
				s.SetIgnore(wechatapp.FieldPlatformID)
			}
		}
	}))
	return u
}

